#![cfg(feature = "header")]
//! `include/aphrody_av.h` is generated by cbindgen from `src/ffi.rs`; this fails when it drifts.

#[test]
fn committed_c_header_matches_cbindgen_output() {
    let manifest = env!("CARGO_MANIFEST_DIR");
    let generated = cbindgen::generate(manifest).expect("cbindgen");
    let mut buffer = Vec::new();
    generated.write(&mut buffer);
    let committed =
        std::fs::read_to_string(std::path::Path::new(manifest).join("include/aphrody_av.h"))
            .expect("committed header");
    assert_eq!(
        String::from_utf8(buffer).expect("utf8"),
        committed,
        "regenerate with: cargo run -p aphrody_av --features header --bin aphrody-av-header"
    );
}
